import{_ as t,o as d,c as o,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Studio Plans — Plan kỹ thuật","description":"","frontmatter":{},"headers":[],"relativePath":"feature/studio-personal-plans/plan.md","filePath":"feature/studio-personal-plans/plan.md"}'),c={name:"feature/studio-personal-plans/plan.md"};function n(i,e,s,r,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="studio-plans-—-plan-ky-thuat" tabindex="-1">Studio Plans — Plan kỹ thuật <a class="header-anchor" href="#studio-plans-—-plan-ky-thuat" aria-label="Permalink to &quot;Studio Plans — Plan kỹ thuật&quot;">​</a></h1><h2 id="_1-huong-tiep-can-it-thay-đoi-nhat" tabindex="-1">1. Hướng tiếp cận (ít thay đổi nhất) <a class="header-anchor" href="#_1-huong-tiep-can-it-thay-đoi-nhat" aria-label="Permalink to &quot;1. Hướng tiếp cận (ít thay đổi nhất)&quot;">​</a></h2><p>Công ty Personal <strong>đã là một dòng <code>agencies</code></strong>, nên gói Studio đi qua đúng bộ máy billing Agency hiện có (<code>agency_subscriptions</code>, <code>billing_orders</code>, <code>agency_subscription_periods</code>, <code>credit_grants</code>, SePay webhook, trả trước 3/6/12 tháng, cấp credit theo tháng). Không tạo bảng mới.</p><ul><li>Mã gói mới <code>STUDIO_FREE | STUDIO_PLUS | STUDIO_PRO</code>. Cột sinh <code>billing_scope</code> tự ra <code>&#39;AGENCY&#39;</code> (chỉ <code>PERSONAL</code> mới là <code>&#39;USER&#39;</code>), nên mọi FK/CHECK <code>plan_billing_scope=&#39;AGENCY&#39;</code> giữ nguyên.</li><li>&quot;Dòng gói&quot; suy ra từ tiền tố mã: <code>STUDIO_*</code> = Studio, còn lại = Agency.</li><li>Thay mọi chỗ gắn cứng <code>&#39;BASIC&#39;</code> là &quot;gói miễn phí&quot; bằng <strong>gói miễn phí theo <code>company_type</code></strong> (<code>PERSONAL → STUDIO_FREE</code>, <code>AGENCY → BASIC</code>).</li><li>Thay mọi chỗ gắn cứng <code>&#39;PLUS&#39;</code> là &quot;gói bán được duy nhất&quot; bằng <strong><code>planCode</code> từ request</strong> + bảng thứ hạng.</li></ul><p>Một helper Java dùng chung <code>PlanLine</code>:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> String </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">freeCode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(String companyType)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &quot;PERSONAL&quot; -&gt; STUDIO_FREE, else BASIC</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> String </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">line</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(String planCode)         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// STUDIO_* -&gt; STUDIO, else AGENCY</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rank</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(String planCode)            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// BASIC/STUDIO_FREE 0, PLUS/STUDIO_PLUS 1, ENTERPRISE/STUDIO_PRO 2</span></span></code></pre></div><p>SQL &quot;gói hiệu lực&quot; hiện có (<code>CASE WHEN expired THEN &#39;BASIC&#39; ELSE p.code END</code>) đổi thành <code>CASE WHEN expired THEN (CASE WHEN a.company_type=&#39;PERSONAL&#39; THEN &#39;STUDIO_FREE&#39; ELSE &#39;BASIC&#39; END) ELSE p.code END</code> (join <code>agencies a</code>).</p><h2 id="_2-db-—-brandhub-infrastructure-docs-database-migrations-2026-11-22-studio-plans-sql" tabindex="-1">2. DB — <code>brandhub-infrastructure/docs/database/migrations/2026-11-22-studio-plans.sql</code> <a class="header-anchor" href="#_2-db-—-brandhub-infrastructure-docs-database-migrations-2026-11-22-studio-plans-sql" aria-label="Permalink to &quot;2. DB — `brandhub-infrastructure/docs/database/migrations/2026-11-22-studio-plans.sql`&quot;">​</a></h2><p>Idempotent, <code>psql -X -v ON_ERROR_STOP=1</code>, chạy sau <code>2026-11-22-agency-company-type.sql</code>.</p><ol><li><code>billing_plan_versions_code_check</code> → thêm <code>STUDIO_FREE, STUDIO_PLUS, STUDIO_PRO</code>.</li><li>Insert 3 version 1 (ON CONFLICT DO NOTHING):</li></ol><table tabindex="0"><thead><tr><th>code</th><th>price_monthly</th><th>ws</th><th>members</th><th>clients</th><th>storage bytes</th><th>credits</th><th>jobs</th><th>version</th><th>trash</th><th>activity</th><th>sellable</th></tr></thead><tbody><tr><td>STUDIO_FREE</td><td>0</td><td>1</td><td>1</td><td>0</td><td>2147483648</td><td>100</td><td>1</td><td>7</td><td>7</td><td>30</td><td>true</td></tr><tr><td>STUDIO_PLUS</td><td>99000</td><td>3</td><td>1</td><td>0</td><td>5368709120</td><td>900</td><td>1</td><td>30</td><td>30</td><td>90</td><td>true</td></tr><tr><td>STUDIO_PRO</td><td>299000</td><td>10</td><td>3</td><td>0</td><td>32212254720</td><td>2400</td><td>2</td><td>90</td><td>30</td><td>180</td><td>true</td></tr></tbody></table><p><code>features = &#39;{&quot;product_line&quot;:&quot;STUDIO&quot;}&#39;</code>. 3. <code>billing_plan_cycle_prices</code>: Plus 3/6/12 = 279000/529000/949000; Pro = 849000/1599000/2869000. 4. Chuyển công ty Personal đang <code>BASIC</code> sang <code>STUDIO_FREE</code> (<code>UPDATE agency_subscriptions s SET plan_version_id=&lt;STUDIO_FREE v1&gt; FROM agencies a, billing_plan_versions p WHERE a.id=s.agency_id AND a.company_type=&#39;PERSONAL&#39; AND p.id=s.plan_version_id AND p.code=&#39;BASIC&#39;</code>). 5. ENTERPRISE: insert version mới copy từ version mới nhất, <code>storage_limit_bytes = 500000000000</code> (giá, cycle prices giữ nguyên; copy <code>billing_plan_cycle_prices</code> sang version mới; version cũ <code>is_sellable=false</code>) — AC12. 6. Ghi <code>brandhub_schema_migrations(&#39;20261122_studio_plans_v1&#39;)</code>. 6. Đồng bộ <code>init-postgres-v2.sql</code> (CHECK + seed) cho môi trường mới.</p><h2 id="_3-backend-brandhub-business-service" tabindex="-1">3. Backend (<code>brandhub-business-service</code>) <a class="header-anchor" href="#_3-backend-brandhub-business-service" aria-label="Permalink to &quot;3. Backend (`brandhub-business-service`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Thay đổi</th></tr></thead><tbody><tr><td><code>service/PlanLine.java</code> (mới, nhỏ)</td><td><code>freeCode</code>, <code>line</code>, <code>rank</code> + unit test</td></tr><tr><td><code>service/impl/AgencyServiceImpl.java</code></td><td><code>createAgency</code>: seed gói <code>freeCode(companyType)</code> thay <code>BASIC</code>; <code>loadPlanCodes</code> dùng SQL hiệu lực mới</td></tr><tr><td><code>seed/SubscriptionCreditSeeder.java</code></td><td>seed theo <code>company_type</code></td></tr><tr><td><code>service/AgencySubscriptionLifecycle.java</code></td><td>hết hạn → gói miễn phí theo <code>company_type</code>; nội dung thông báo theo dòng (Studio / Plus)</td></tr><tr><td><code>service/AgencyPlanEntitlementService.java</code></td><td>SQL hiệu lực mới; <code>defaultsForCode</code> thêm 3 STUDIO; <code>resolveBasicFromCatalogOrDefaults</code> → <code>resolveFree(code)</code>; <code>max_clients</code> = 0 hợp lệ cho STUDIO; <code>requireWorkspaceSlot</code> đếm cả workspace chế độ Personal (trừ <code>isPersonalDefault</code> của công ty Agency cũ)</td></tr><tr><td><code>service/impl/WorkspaceServiceImpl.java</code></td><td>bỏ điều kiện <code>mode != PERSONAL</code> khi gọi <code>requireWorkspaceSlot</code> (create + restore); <code>updateSettings</code> PERSONAL→AGENCY gọi <code>requireWorkspaceSlot</code></td></tr><tr><td><code>dto/request/CreateAgencyBillingOrderRequest.java</code></td><td>`@Pattern(&quot;PLUS</td></tr><tr><td><code>service/AgencyBillingService.java</code></td><td><code>createSubscriptionOrder</code>: plan theo <code>planCode</code>; kiểm dòng = dòng công ty; kiểm hạng (UPGRADE: rank đích &gt; rank hiện tại; RENEWAL: đích = hiện tại hoặc EXPIRED); proration khi hiện tại là gói trả phí cùng dòng &amp; chưa hết hạn; payload hash + snapshot chứa <code>planCode</code>, <code>prorationCredit</code>. <code>fulfill</code>: kiểm hạng như trên; upgrade giữa kỳ đóng kỳ CURRENT tại <code>paidAt</code> và <strong>không</strong> đẩy <code>periodStart</code> về <code>lastEnd</code>; outbox payload dùng planCode thật. Thêm <code>quoteUpgrade(...)</code></td></tr><tr><td><code>service/BillingPlanCatalogService.java</code></td><td>lọc theo dòng (<code>agencyId</code> → company_type); <code>checkoutEnabled</code> = sellable &amp;&amp; price&gt;0 &amp;&amp; mã bán qua SePay (PLUS, STUDIO_PLUS, STUDIO_PRO); thứ tự theo rank; thêm <code>productLine</code></td></tr><tr><td><code>controller/BillingPlanController.java</code></td><td><code>@RequestParam(required=false) UUID agencyId</code></td></tr><tr><td><code>controller/BillingController.java</code></td><td><code>GET /agencies/{agencyId}/upgrade-quote</code></td></tr><tr><td><code>dto/response/BillingPlanResponse.java</code></td><td>thêm <code>productLine</code>; mặc định newsletter/support cho STUDIO_*</td></tr><tr><td><code>service/NewsletterQuotaService.java</code></td><td>SQL hiệu lực mới</td></tr><tr><td><code>service/material/StorageQuotaService.java</code></td><td><code>p.code IN (&#39;PLUS&#39;,&#39;ENTERPRISE&#39;)</code> → thêm <code>STUDIO_PLUS, STUDIO_PRO</code></td></tr><tr><td><code>service/admin/AdminRevenueService.java</code></td><td>thứ tự nhóm thêm STUDIO_*</td></tr></tbody></table><h3 id="proration-ac6" tabindex="-1">Proration (AC6) <a class="header-anchor" href="#proration-ac6" aria-label="Permalink to &quot;Proration (AC6)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cur = kỳ CURRENT (agency_subscription_periods join billing_orders o on o.id = order_id)</span></span>\n<span class="line"><span>paid = o.amount ; total = ends_at - starts_at ; left = max(0, ends_at - now)</span></span>\n<span class="line"><span>credit = floor(paid * left / total / 1000) * 1000</span></span>\n<span class="line"><span>amount = cyclePrice(target, months) - credit ; amount &lt;= 0 -&gt; BILLING_ORDER_CONFLICT</span></span></code></pre></div><p>Chỉ áp dụng khi <code>line(current)=line(target)</code>, <code>rank(current)&gt;=1</code>, subscription ACTIVE chưa hết hạn, không có kỳ FUTURE. Hash idempotency gồm <code>planCode</code> + <code>planVersionId</code> + <code>action</code> + <code>months</code> (PLUS giữ định dạng cũ); <code>credit</code> chỉ lưu trong <code>product_snapshot</code> vì nó đổi theo thời gian — đưa vào hash thì retry cùng key vài phút sau sẽ bị conflict thay vì trả lại đúng đơn.</p><h2 id="_4-web-brandhub-web" tabindex="-1">4. Web (<code>brandhub-web</code>) <a class="header-anchor" href="#_4-web-brandhub-web" aria-label="Permalink to &quot;4. Web (`brandhub-web`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Thay đổi</th></tr></thead><tbody><tr><td><code>src/services/agencyBillingService.ts</code></td><td><code>getPlans(agencyId?)</code>, <code>getUpgradeQuote(agencyId, planCode, months)</code>, kiểu <code>productLine</code></td></tr><tr><td><code>src/pages/subscription/plans.tsx</code> + <code>hooks/*</code></td><td>truyền <code>currentAgencyId</code>; dòng Studio ẩn <code>PlanComparisonMatrix</code> Agency</td></tr><tr><td><code>src/pages/subscription/components/CatalogPlanCard.tsx</code></td><td>tên/tagline/feature Studio qua i18n; nút mua gửi đúng <code>planCode</code>; hiện proration</td></tr><tr><td><code>src/pages/subscription/checkout.tsx</code>, <code>OrderSummaryCard.tsx</code></td><td>dòng &quot;Trừ phần Plus còn lại&quot; khi có <code>prorationCredit</code></td></tr><tr><td><code>src/lib/planPrice.ts</code></td><td>nhãn gói STUDIO_*</td></tr><tr><td><code>src/components/layout/sidebar/OrgSwitcherDropdown.tsx</code>, <code>src/pages/agency/components/hub/AgencyHubCard.tsx</code></td><td>badge tên gói Studio</td></tr><tr><td><code>src/i18n/locales/vi/subscription.json</code>, <code>src/i18n/locales/en/subscription.json</code></td><td>key <code>subscription.studio.*</code></td></tr><tr><td><code>src/pages/workspace/hooks/useCreateWorkspace.ts</code>, <code>components/CreateWorkspaceForm.tsx</code></td><td>AC13a: agency <code>companyType=PERSONAL</code> → khoá <code>workspaceMode=PERSONAL</code>, ẩn chọn chế độ / ClientInvitePicker / trường doanh nghiệp</td></tr><tr><td><code>src/pages/tasks/index.tsx</code></td><td>AC13b: Personal → <code>campaignId={null}</code> cho QuickCreate, ẩn banner chiến dịch</td></tr><tr><td><code>src/pages/workspace/detail.tsx</code></td><td>AC13c: ẩn khối chuyển chế độ khi công ty Personal</td></tr><tr><td><code>AgencyPlanEntitlementService.defaultsForCode</code></td><td>ENTERPRISE fallback storage 500 GB (AC12)</td></tr></tbody></table><h2 id="_5-thu-tu-build" tabindex="-1">5. Thứ tự build <a class="header-anchor" href="#_5-thu-tu-build" aria-label="Permalink to &quot;5. Thứ tự build&quot;">​</a></h2><p>DB migration → <code>PlanLine</code> + test → entitlement/lifecycle/createAgency → catalog API → order + proration + quote → web catalog/checkout → i18n → kiểm tra light/dark → test.md.</p><h2 id="_6-rui-ro" tabindex="-1">6. Rủi ro <a class="header-anchor" href="#_6-rui-ro" aria-label="Permalink to &quot;6. Rủi ro&quot;">​</a></h2><ul><li>Billing đụng tiền thật: mọi thay đổi <code>AgencyBillingService</code> phải có test cho upgrade, renewal, cross-line, proration.</li><li><code>billing_guard_plan_version</code> cấm sửa version → giá sai phải tạo version 2, không UPDATE.</li><li>Prod: chạy <code>2026-11-22-agency-company-type.sql</code> <strong>trước</strong> <code>2026-11-22-studio-plans.sql</code>.</li><li>Web/business worktree đang có nhiều sửa đổi chưa commit của phiên khác — chỉ commit file của feature này.</li></ul>',23)])])}const u=t(c,[["render",n]]);export{g as __pageData,u as default};
